Tool response:
Tool: set_default_appointment_type
Description: Update the appointment type with the given ID to be the default for new patients.
This will disable any previously set default appointment type.
Parameters:
    {
      "type": "object",
      "properties": {
        "appointment_type_id": {
          "type": "integer",
          "title": "Appointment Type Id"
        }
      },
      "required": [
        "appointment_type_id"
      ]
    }

Tool response:
Tool: enable_appointment_type_for_provider
Description: Enable the specified appointment type for the given provider.
If the provider does not already have this appointment type configured, it will be added with is_enabled = 1.
Parameters:
    {
      "type": "object",
      "properties": {
        "provider_id": {
          "type": "integer",
          "description": "The ID of the provider",
          "title": "Provider Id"
        },
        "appointment_type_id": {
          "type": "integer",
          "description": "The ID of the appointment type to enable",
          "title": "Appointment Type Id"
        }
      },
      "required": [
        "provider_id",
        "appointment_type_id"
      ]
    }

Tool response:
Tool: get_provider_appointment_types
Description: Retrieve all appointment types associated with the given provider, indicating whether each is enabled or disabled.
Parameters:
    {
      "type": "object",
      "properties": {
        "provider_id": {
          "type": "integer",
          "description": "The ID of the provider",
          "title": "Provider Id"
        }
      },
      "required": [
        "provider_id"
      ]
    }
